`timescale 1ns/1ps
// Independent answers are generated by tests/run_gcm.py using OpenSSL EVP.
// This bench contains no AES/GHASH implementation shared with the DUT.
module aes_gcm_engine_tb #(
    parameter int AES_KEY_W = 256,
    parameter int MEM_DATA_W = 128,
    parameter int MAX_TXN_BYTES = 1031,
    parameter int MAX_AAD_BYTES = 1033
);
    localparam int BYTES = MEM_DATA_W / 8;
    localparam int ROUNDS = (AES_KEY_W == 128) ? 10 : 14;
    localparam int LANES = MEM_DATA_W / 128;
    localparam int QUARANTINE_BEATS = (MAX_TXN_BYTES + BYTES - 1) / BYTES;
    logic clk = 0, reset = 1, clear = 0;
    logic start_valid = 0, decrypt = 0;
    wire start_ready;
    logic [AES_KEY_W-1:0] key_in = '0;
    logic [95:0] iv = '0;
    logic [127:0] expected_tag = '0;
    logic [31:0] aad_bytes = 0, payload_bytes = 0;
    logic aad_valid = 0, aad_last = 0;
    wire aad_ready;
    logic [MEM_DATA_W-1:0] aad_data = '0;
    logic [BYTES-1:0] aad_keep = '0;
    logic in_valid = 0, in_last = 0;
    wire in_ready;
    logic [MEM_DATA_W-1:0] in_data = '0;
    logic [BYTES-1:0] in_keep = '0;
    wire out_valid, out_last, result_valid;
    logic out_ready = 0, result_ready = 0;
    wire [MEM_DATA_W-1:0] out_data;
    wire [BYTES-1:0] out_keep;
    wire [127:0] result_tag;
    wire [2:0] result_error;
    logic [AES_KEY_W-1:0] vector_key;
    logic [95:0] vector_iv;
    logic [127:0] vector_tag;
    logic [8*MAX_AAD_BYTES-1:0] vector_aad;
    logic [8*MAX_TXN_BYTES-1:0] vector_plain, vector_cipher;
    int vector_aad_bytes, vector_payload_bytes;
    int vector_index = -1, checked = 0, cancelled = 0, failed_auth = 0;
    int failed_framing = 0, failed_length = 0;
    int continuous_bursts = 0;
    int tag_bits = 128;
    bit smoke = 0;
    logic [31:0] rng = 32'h7250d1c3;
    string vector_path;

    always #5 clk = ~clk;
    aes_gcm_engine #(.AES_KEY_W(AES_KEY_W), .MEM_DATA_W(MEM_DATA_W),
        .MAX_TXN_BYTES(MAX_TXN_BYTES), .MAX_AAD_BYTES(MAX_AAD_BYTES)) dut (.*);

    wire [LANES-1:0] lane_secrets_erased;
    for (genvar lane = 0; lane < LANES; lane++) begin : g_erase_monitor
        wire [ROUNDS:0] state_erased;
        wire [ROUNDS-1:0] key_erased;
        for (genvar stage = 0; stage <= ROUNDS; stage++) begin : g_state
            assign state_erased[stage] = (dut.ctr.g_lane[lane].aes.state_pipe[stage] === 128'b0);
        end
        for (genvar stage = 0; stage < ROUNDS; stage++) begin : g_key
            assign key_erased[stage] = (dut.ctr.g_lane[lane].aes.key_pipe[stage] === {AES_KEY_W{1'b0}});
        end
        assign lane_secrets_erased[lane] = (&state_erased) && (&key_erased);
    end

    task automatic ck(input logic condition, input string what);
        if (condition !== 1'b1)
            $fatal(1, "GCM AES%0d bus%0d vector%0d transaction%0d: %s",
                   AES_KEY_W, MEM_DATA_W, vector_index, checked, what);
    endtask

    function automatic [31:0] random_word();
        rng = rng ^ (rng << 13);
        rng = rng ^ (rng >> 17);
        rng = rng ^ (rng << 5);
        return rng;
    endfunction

    function automatic [BYTES-1:0] expected_keep(input int bytes_left);
        logic [BYTES-1:0] value;
        value = '0;
        for (int index = 0; index < BYTES; index++)
            if (index < bytes_left) value[BYTES-1-index] = 1'b1;
        return value;
    endfunction

    task automatic check_erased();
        ck(dut.key_reg === {AES_KEY_W{1'b0}} && dut.iv_reg === 96'b0 &&
           dut.h_reg === 128'b0 && dut.tag_mask === 128'b0 &&
           dut.expected_tag_reg === 128'b0, "private command/key/hash state erased");
        for (int index = 0; index < QUARANTINE_BEATS; index++)
            ck(dut.quarantine_data[index] === {MEM_DATA_W{1'b0}} &&
               dut.quarantine_keep[index] === {BYTES{1'b0}} &&
               dut.quarantine_last[index] === 1'b0,
               $sformatf("quarantine entry %0d erased", index));
        ck(dut.ctr.key_reg === {AES_KEY_W{1'b0}} && dut.ctr.counter_reg === 128'b0 &&
           dut.ctr.valid_pipe === {(ROUNDS+1){1'b0}} &&
           dut.hash.h_reg === 128'b0 && dut.hash.accumulator === 128'b0 &&
           dut.hash.result_reg === 128'b0 && (&lane_secrets_erased),
           "GCTR, lane AES, and GHASH secrets erased");
        for (int stage = 0; stage <= ROUNDS; stage++)
            ck(dut.setup_aes.state_pipe[stage] === 128'b0 &&
               dut.ctr.data_pipe[stage] === {MEM_DATA_W{1'b0}} &&
               dut.ctr.keep_pipe[stage] === {BYTES{1'b0}}, "setup/GCTR data pipelines erased");
        for (int stage = 0; stage < ROUNDS; stage++)
            ck(dut.setup_aes.key_pipe[stage] === {AES_KEY_W{1'b0}}, "setup AES key pipeline erased");
    endtask

    task automatic check_quiet();
        ck(!out_valid && !result_valid, "cancel/idle suppresses output and result");
        ck(out_data === {MEM_DATA_W{1'b0}} && out_keep === {BYTES{1'b0}} &&
           out_last === 1'b0 && result_tag === 128'b0,
           "invalid output pins do not expose previous data");
    endtask

    task automatic cancel_transaction(input bit use_reset);
        @(negedge clk);
        start_valid = 0;
        aad_valid = 0;
        in_valid = 0;
        out_ready = 1;
        result_ready = 1;
        reset = use_reset;
        clear = !use_reset;
        #1;
        ck(!start_ready && !aad_ready && !in_ready, "cancellation suppresses handshakes immediately");
        check_quiet();
        repeat (2) begin
            @(posedge clk); #1;
            check_erased();
            check_quiet();
        end
        @(negedge clk);
        reset = 0;
        clear = 0;
        out_ready = 0;
        result_ready = 0;
        repeat (2) begin
            @(posedge clk); #1;
            ck(start_ready, "ready following cancellation");
            check_quiet();
            check_erased();
        end
    endtask

    // fault: 0 none, 1 tag bit, 2 ciphertext byte, 3 AAD byte, 4 IV, 5 key, 6 X tag.
    // framing: 1/2/3 payload zero/hole/short keep, 4/5 early/missing last;
    //          6/7/8 AAD zero/hole/short keep, 9/10 early/missing last.
    //          11/12 payload zero keep / early last while ciphertext stalled.
    // cancel_phase: setup, mid-AAD, mid-payload, output stall, result stall,
    //               or final-input processing; each is run with reset and clear.
    // length_fault: payload+1, AAD+1, payload all-ones, AAD all-ones.
    task automatic run_transaction(input bit dec, input int fault, input int bit_index,
                                   input int framing, input int cancel_phase,
                                   input bit cancel_reset, input int length_fault);
        int apos, ppos, opos, steps, take, output_holds, result_holds;
        int expected_error, prior_result_error;
        int prior_payload_step, prior_output_step;
        bit continuous, fault_while_stalled;
        logic done, a_fire, p_fire, cancel_now, stalled_output, stalled_result;
        logic [MEM_DATA_W-1:0] prior_out_data;
        logic [BYTES-1:0] prior_out_keep;
        logic prior_out_last;
        logic [127:0] prior_result_tag;
        logic [7:0] expected_byte;
        expected_error = (length_fault != 0) ? 3 : (framing != 0) ? 2 : (fault != 0) ? 1 : 0;
        apos = 0;
        ppos = 0;
        opos = 0;
        steps = 0;
        output_holds = 0;
        result_holds = 0;
        done = 0;
        stalled_output = 0;
        stalled_result = 0;
        prior_payload_step = -1;
        prior_output_step = -1;
        continuous = (vector_index % 3 == 0) && fault == 0 && framing == 0 &&
                     cancel_phase == 0 && length_fault == 0;
        fault_while_stalled = 0;
        @(negedge clk);
        ck(start_ready, "command accepted only from idle");
        start_valid = 1;
        decrypt = dec;
        key_in = vector_key;
        iv = vector_iv;
        expected_tag = vector_tag;
        if (fault == 1) expected_tag[bit_index] = ~expected_tag[bit_index];
        if (fault == 6) expected_tag[bit_index] = 1'bx;
        if (fault == 4) iv[bit_index % 96] = ~iv[bit_index % 96];
        if (fault == 5) key_in[bit_index % AES_KEY_W] = ~key_in[bit_index % AES_KEY_W];
        aad_bytes = vector_aad_bytes;
        payload_bytes = vector_payload_bytes;
        case (length_fault)
            1: payload_bytes = MAX_TXN_BYTES + 1;
            2: aad_bytes = MAX_AAD_BYTES + 1;
            3: payload_bytes = 32'hffffffff;
            4: aad_bytes = 32'hffffffff;
        endcase
        aad_valid = 0;
        in_valid = 0;
        out_ready = 0;
        result_ready = 0;
        @(posedge clk); #1;
        ck(!start_ready, "command reserves engine until completion");
        while (!done) begin
            @(negedge clk);
            // These pins must be captured at start, never sampled again.
            key_in = ~vector_key;
            iv = ~vector_iv;
            expected_tag = ~vector_tag;
            aad_bytes = 32'hffffffff;
            payload_bytes = 32'hffffffff;
            decrypt = !dec;
            start_valid = ((steps % 11) == 3) && !result_valid;
            if (out_valid) output_holds++;
            if (result_valid) result_holds++;
            out_ready = continuous || (output_holds > 7 && ((random_word() % 4) != 0));
            result_ready = result_holds > 6;
            if (!aad_valid && apos < vector_aad_bytes && length_fault == 0 &&
                !result_valid && (continuous || ((random_word() % 3) != 0))) begin
                take = ((vector_aad_bytes - apos) < BYTES) ? vector_aad_bytes - apos : BYTES;
                aad_data = '1; // Deliberately poison ignored trailing bytes.
                for (int index = 0; index < take; index++) begin
                    aad_data[MEM_DATA_W-1-8*index -: 8] = vector_aad[(vector_aad_bytes-1-apos-index)*8 +: 8];
                    if (fault == 3 && apos + index == (bit_index == 0 ? 0 : vector_aad_bytes-1))
                        aad_data[MEM_DATA_W-1-8*index -: 8] ^= 8'h80;
                end
                aad_keep = expected_keep(take);
                aad_last = (apos + take == vector_aad_bytes);
                if (apos == 0) begin
                    if (framing == 6) aad_keep = '0;
                    if (framing == 7) aad_keep[BYTES-2] = 0;
                    if (framing == 8) aad_keep[BYTES-take] = 0;
                    if (framing == 9) aad_last = 1;
                end
                if (framing == 10 && aad_last) aad_last = 0;
                aad_valid = 1;
            end
            if (!in_valid && ppos < vector_payload_bytes && length_fault == 0 &&
                !result_valid && (framing < 11 || ppos == 0 || out_valid) &&
                (continuous || ((random_word() % 3) != 0))) begin
                take = ((vector_payload_bytes - ppos) < BYTES) ? vector_payload_bytes - ppos : BYTES;
                in_data = '1;
                for (int index = 0; index < take; index++) begin
                    if (dec)
                        in_data[MEM_DATA_W-1-8*index -: 8] = vector_cipher[(vector_payload_bytes-1-ppos-index)*8 +: 8];
                    else
                        in_data[MEM_DATA_W-1-8*index -: 8] = vector_plain[(vector_payload_bytes-1-ppos-index)*8 +: 8];
                    if (fault == 2 && ppos + index == (bit_index == 0 ? 0 : vector_payload_bytes-1))
                        in_data[MEM_DATA_W-1-8*index -: 8] ^= 8'h01;
                end
                in_keep = expected_keep(take);
                in_last = (ppos + take == vector_payload_bytes);
                if (ppos == 0) begin
                    if (framing == 1) in_keep = '0;
                    if (framing == 2) in_keep[BYTES-2] = 0;
                    if (framing == 3) in_keep[BYTES-take] = 0;
                    if (framing == 4) in_last = 1;
                end
                if (framing == 5 && in_last) in_last = 0;
                if (framing >= 11 && ppos == BYTES) begin
                    ck(out_valid && !out_ready, "malformed beat presented with prior ciphertext stalled");
                    fault_while_stalled = 1;
                    if (framing == 11) in_keep = '0;
                    if (framing == 12) in_last = 1;
                end
                in_valid = 1;
            end
            @(posedge clk);
            ck(!start_ready, "busy start attempts never accepted");
            a_fire = aad_valid && aad_ready;
            p_fire = in_valid && in_ready;
            if (length_fault != 0)
                ck(!aad_ready && !in_ready && !out_valid, "oversized command consumes no data");
            if (dec && expected_error != 0)
                ck(!out_valid && out_data === {MEM_DATA_W{1'b0}}, "failed decrypt never exposes plaintext");
            if (dec && out_valid)
                ck(apos == vector_aad_bytes && ppos == vector_payload_bytes,
                   "plaintext release requires the entire authenticated transaction");
            if (stalled_output && framing == 0)
                ck(out_valid && out_data === prior_out_data && out_keep === prior_out_keep &&
                   out_last === prior_out_last, "output remains stable through backpressure");
            stalled_output = out_valid && !out_ready;
            prior_out_data = out_data;
            prior_out_keep = out_keep;
            prior_out_last = out_last;
            if (out_valid && out_ready) begin
                if (continuous && prior_output_step >= 0)
                    ck(steps == prior_output_step + 1, "unstalled output sustains one memory beat per cycle");
                prior_output_step = steps;
                ck(opos < vector_payload_bytes, "no duplicate or excess output beat");
                take = ((vector_payload_bytes-opos) < BYTES) ? vector_payload_bytes-opos : BYTES;
                ck(out_keep === expected_keep(take), "output keep matches declared byte count");
                ck(out_last === (opos + take == vector_payload_bytes), "output last matches declared length");
                for (int index = 0; index < BYTES; index++) begin
                    expected_byte = 0;
                    if (index < take) begin
                        if (dec) expected_byte = vector_plain[(vector_payload_bytes-1-opos-index)*8 +: 8];
                        else expected_byte = vector_cipher[(vector_payload_bytes-1-opos-index)*8 +: 8];
                    end
                    ck(out_data[MEM_DATA_W-1-8*index -: 8] === expected_byte,
                       $sformatf("OpenSSL output byte %0d expected %02h got %02h",
                           opos+index, expected_byte, out_data[MEM_DATA_W-1-8*index -: 8]));
                end
                opos += take;
            end
            if (stalled_result)
                ck(result_valid && result_tag === prior_result_tag && result_error == prior_result_error,
                   "result remains stable through backpressure");
            stalled_result = result_valid && !result_ready;
            prior_result_tag = result_tag;
            prior_result_error = result_error;
            if (result_valid) begin
                ck(result_error === 3'(expected_error),
                   $sformatf("result error expected %0d got %0d (fault=%0d framing=%0d)",
                             expected_error, result_error, fault, framing));
                if (expected_error == 0) ck(opos == vector_payload_bytes, "success waits for every output handshake");
                if (dec || expected_error != 0)
                    ck(result_tag === 128'b0, "decrypt/failure never exposes a computed tag");
                else ck(result_tag === vector_tag,
                        $sformatf("OpenSSL GCM tag expected %032h got %032h", vector_tag, result_tag));
                ck(!out_valid, "terminal status and data output are separate");
                check_erased();
                if (result_ready) done = 1;
            end
            if (a_fire) apos += ((vector_aad_bytes-apos) < BYTES) ? vector_aad_bytes-apos : BYTES;
            if (p_fire) begin
                if (continuous && prior_payload_step >= 0)
                    ck(steps == prior_payload_step + 1, "unstalled input sustains one memory beat per cycle");
                prior_payload_step = steps;
                ppos += ((vector_payload_bytes-ppos) < BYTES) ? vector_payload_bytes-ppos : BYTES;
            end
            steps++;
            ck(steps < 20000, $sformatf("bounded progress; aad=%0d payload=%0d output=%0d state=%0d",
                                     apos, ppos, opos, dut.state));
            cancel_now = (cancel_phase == 1 && steps == 2) ||
                         (cancel_phase == 2 && apos > 0 && apos < vector_aad_bytes) ||
                         (cancel_phase == 3 && ppos > 0 && ppos < vector_payload_bytes) ||
                         (cancel_phase == 4 && out_valid && output_holds == 2) ||
                         (cancel_phase == 5 && result_valid && result_holds == 2) ||
                         (cancel_phase == 6 && ppos == vector_payload_bytes && ppos != 0 && !out_valid);
            #1;
            if (a_fire) aad_valid = 0;
            if (p_fire) in_valid = 0;
            if (cancel_now) begin
                cancel_transaction(cancel_reset);
                cancelled++;
                done = 1;
            end
        end
        if (cancel_phase != 0) ck(cancel_now, "requested cancellation phase was reached");
        if (framing >= 11) ck(fault_while_stalled, "covered malformed input during ciphertext backpressure");
        @(negedge clk);
        start_valid = 0;
        aad_valid = 0;
        in_valid = 0;
        out_ready = 0;
        result_ready = 0;
        @(posedge clk); #1;
        ck(start_ready, "ready for next command after completion");
        check_quiet();
        check_erased();
        checked++;
        if (continuous && vector_payload_bytes > BYTES) continuous_bursts++;
        if (expected_error == 1) failed_auth++;
        if (expected_error == 2) failed_framing++;
        if (expected_error == 3) failed_length++;
    endtask

    initial begin : campaign
        int stream, count, scanned, ignored;
        ignored = $value$plusargs("tag_bits=%d", tag_bits);
        smoke = $test$plusargs("smoke");
        ck($value$plusargs("vectors=%s", vector_path), "requires +vectors generated by tests/run_gcm.py");
        stream = $fopen(vector_path, "r");
        ck(stream != 0, "open oracle vectors");
        scanned = $fscanf(stream, "%d\n", count);
        ck(scanned == 1 && count >= 3, "fixture contains NIST and adversarial vectors");
        repeat (3) @(posedge clk);
        @(negedge clk);
        reset = 0;
        for (vector_index = 0; vector_index < count; vector_index++) begin
            scanned = $fscanf(stream, "%h %h %d %d %h %h %h %h\n",
                vector_key, vector_iv, vector_aad_bytes, vector_payload_bytes,
                vector_tag, vector_aad, vector_plain, vector_cipher);
            ck(scanned == 8, "read complete oracle vector");
            ck(vector_aad_bytes <= MAX_AAD_BYTES && vector_payload_bytes <= MAX_TXN_BYTES,
               "fixture lengths fit testbench bounds");
            run_transaction(0, 0, 0, 0, 0, 0, 0);
            run_transaction(1, 0, 0, 0, 0, 0, 0);
            if (vector_index == 2 && !smoke) begin
                for (int bit_index = 0; bit_index < tag_bits; bit_index++)
                    run_transaction(1, 1, bit_index, 0, 0, 0, 0);
                for (int fault = 2; fault <= 5; fault++)
                    for (int bit_index = 0; bit_index < 2; bit_index++)
                        run_transaction(1, fault, bit_index == 0 ? 0 : 95, 0, 0, 0, 0);
                run_transaction(1, 6, 0, 0, 0, 0, 0);
                run_transaction(1, 6, 127, 0, 0, 0, 0);
                run_transaction(0, 0, 0, 11, 0, 0, 0);
                run_transaction(0, 0, 0, 12, 0, 0, 0);
                for (int dec = 0; dec < 2; dec++) begin
                    for (int framing = 1; framing <= 10; framing++)
                        run_transaction(1'(dec), 0, 0, framing, 0, 0, 0);
                    for (int fault = 1; fault <= 4; fault++)
                        run_transaction(1'(dec), 0, 0, 0, 0, 0, fault);
                    for (int method = 0; method < 2; method++)
                        for (int phase = 1; phase <= 6; phase++) begin
                            run_transaction(1'(dec), 0, 0, 0, phase, 1'(method), 0);
                            run_transaction(1'(dec), 0, 0, 0, 0, 0, 0);
                        end
                end
            end
        end
        $fclose(stream);
        if (smoke)
            ck(cancelled == 0 && failed_framing == 0 && failed_length == 0 &&
               failed_auth == 0 && continuous_bursts > 0,
               "wide smoke completed independent vectors and continuous bursts");
        else
            ck(cancelled == 24 && failed_framing == 22 && failed_length == 8 &&
               failed_auth == tag_bits + 10 && continuous_bursts > 0,
               "all directed security/error/cancellation/throughput cases ran");
        $display("PASS GCM AES%0d bus%0d: %0d transactions, %0d oracle vectors, %0d auth failures, %0d framing failures, %0d length failures, %0d cancellations, %0d continuous bursts",
                 AES_KEY_W, MEM_DATA_W, checked, count, failed_auth, failed_framing, failed_length, cancelled, continuous_bursts);
        $finish;
    end
    initial begin
        #100000000;
        $fatal(1, "GCM global watchdog expired");
    end
endmodule
